    // ─── Helpers ──────────────────────────────────────────────

    function fmtMoney(n) {
        if (n == null) return 'N/A';
        if (n >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
        if (n >= 1e6) return '$' + (n / 1e6).toFixed(1) + 'M';
        return '$' + n.toLocaleString();
    }

    function safeGet(key, fallback) {
        try {
            if (typeof GM_getValue === 'function') return GM_getValue(key, fallback);
        } catch (e) {}
        try {
            var v = localStorage.getItem(key);
            return v === null ? fallback : JSON.parse(v);
        } catch (e) {}
        return fallback;
    }

    function safeSet(key, val) {
        try {
            if (typeof GM_setValue === 'function') { GM_setValue(key, val); return; }
        } catch (e) {}
        try {
            localStorage.setItem(key, JSON.stringify(val));
        } catch (e) {}
    }

    function normalizeWeaponName(raw) {
        if (!raw) return '';
        var name = raw.trim().replace(/^The\s+/i, '');
        return name;
    }

    function lookupWeapon(name) {
        if (!name) return null;
        if (weaponPrices[name]) return name;
        var lower = name.toLowerCase();
        if (KNOWN_WEAPONS[lower]) return KNOWN_WEAPONS[lower];
        return null;
    }

    function getMedianPrice(weaponName, rarity) {
        var wData = weaponPrices[weaponName];
        if (wData && wData[rarity]) return wData[rarity][1];
        var cls = WEAPON_CLASS[weaponName];
        if (cls && classPrices[cls] && classPrices[cls][rarity]) return classPrices[cls][rarity][1];
        return null;
    }

    function getBonusMedian(bonusName, rarity) {
        if (!bonusName || !bonusPrices[bonusName]) return null;
        var bData = bonusPrices[bonusName];
        if (bData[rarity]) return bData[rarity][1];
        return null;
    }

    function lookupArmour(name) {
        if (!name) return null;
        if (armourPrices[name]) return name;
        var lower = name.toLowerCase();
        if (KNOWN_ARMOUR[lower]) return KNOWN_ARMOUR[lower];
        return null;
    }

    function getArmourMedianPrice(armourName, rarity) {
        var aData = armourPrices[armourName];
        if (aData && aData[rarity]) return aData[rarity][1];
        var aSet = ARMOUR_SET[armourName];
        if (aSet && armourSetPrices[aSet] && armourSetPrices[aSet][rarity]) return armourSetPrices[aSet][rarity][1];
        return null;
    }

    function getArmourBonusMedian(bonusName, rarity) {
        if (!bonusName || !armourBonusPrices[bonusName]) return null;
        if (armourBonusPrices[bonusName][rarity]) return armourBonusPrices[bonusName][rarity][1];
        return null;
    }

    // ─── Full price array accessors ─────────────────────────

    function getPriceArray(weaponName, rarity) {
        var wData = weaponPrices[weaponName];
        if (wData && wData[rarity]) return wData[rarity];
        var cls = WEAPON_CLASS[weaponName];
        if (cls && classPrices[cls] && classPrices[cls][rarity]) return classPrices[cls][rarity];
        return null;
    }

    function getArmourPriceArray(armourName, rarity) {
        var aData = armourPrices[armourName];
        if (aData && aData[rarity]) return aData[rarity];
        var aSet = ARMOUR_SET[armourName];
        if (aSet && armourSetPrices[aSet] && armourSetPrices[aSet][rarity]) return armourSetPrices[aSet][rarity];
        return null;
    }

    function getBonusPriceArray(bonusName, rarity) {
        if (!bonusName || !bonusPrices[bonusName]) return null;
        if (bonusPrices[bonusName][rarity]) return bonusPrices[bonusName][rarity];
        return null;
    }

    function getArmourBonusPriceArray(bonusName, rarity) {
        if (!bonusName || !armourBonusPrices[bonusName]) return null;
        if (armourBonusPrices[bonusName][rarity]) return armourBonusPrices[bonusName][rarity];
        return null;
    }

    // ─── Combo lookup: weapon+bonus or armour+bonus ──────────

    function getWeaponComboMedian(weaponName, bonusName, rarity) {
        var key = weaponName + '|' + bonusName;
        if (weaponComboPrices[key] && weaponComboPrices[key][rarity]) return weaponComboPrices[key][rarity][1];
        return null;
    }

    function getArmourComboMedian(armourName, bonusName, rarity) {
        var key = armourName + '|' + bonusName;
        if (armourComboPrices[key] && armourComboPrices[key][rarity]) return armourComboPrices[key][rarity][1];
        return null;
    }

    // ─── Percentile computation ──────────────────────────────

    function percentile(sortedArr, p) {
        if (sortedArr.length === 0) return null;
        var idx = (p / 100) * (sortedArr.length - 1);
        var lower = Math.floor(idx);
        var upper = Math.ceil(idx);
        if (lower === upper) return sortedArr[lower];
        return sortedArr[lower] + (sortedArr[upper] - sortedArr[lower]) * (idx - lower);
    }

