    // ─── Gzip decompression ──────────────────────────────────

    async function decompressGzip(arrayBuffer) {
        // Try native DecompressionStream first (fast, available in modern browsers)
        if (typeof DecompressionStream === 'function') {
            try {
                var ds = new DecompressionStream('gzip');
                var writer = ds.writable.getWriter();
                writer.write(new Uint8Array(arrayBuffer));
                writer.close();
                var reader = ds.readable.getReader();
                var chunks = [];
                while (true) {
                    var result = await reader.read();
                    if (result.done) break;
                    chunks.push(result.value);
                }
                var totalLength = chunks.reduce(function(acc, c) { return acc + c.length; }, 0);
                var merged = new Uint8Array(totalLength);
                var offset = 0;
                for (var i = 0; i < chunks.length; i++) {
                    merged.set(chunks[i], offset);
                    offset += chunks[i].length;
                }
                console.log('[RWP] Decompressed with native DecompressionStream');
                return new TextDecoder().decode(merged);
            } catch (e) {
                console.warn('[RWP] DecompressionStream failed, falling back to pako:', e.message);
            }
        }
        // Fallback: pako inflate (works in PDA and older WebViews)
        console.log('[RWP] Decompressing with pako (embedded fallback)');
        var decompressed = _pakoInflate.ungzip(new Uint8Array(arrayBuffer), { to: 'string' });
        return decompressed;
    }

    // ─── CDN fetch wrapper ───────────────────────────────────

    function fetchGzip(url) {
        // Try GM_xmlhttpRequest first (Tampermonkey/Greasemonkey)
        // Note: PDA's GM_xmlhttpRequest doesn't support responseType: 'arraybuffer'
        // so gzip fetch only works on desktop. PDA uses fetchPricesJSON() instead.
        if (typeof GM_xmlhttpRequest === 'function' && !isPDA) {
            return new Promise(function(resolve, reject) {
                GM_xmlhttpRequest({
                    method: 'GET',
                    url: url,
                    responseType: 'arraybuffer',
                    onload: function(resp) {
                        if (resp.status === 200) resolve(resp.response);
                        else reject(new Error('HTTP ' + resp.status));
                    },
                    onerror: function(err) { reject(err); }
                });
            });
        }
        // Fallback using native fetch (works in standard browsers, not PDA)
        return fetch(url).then(function(resp) {
            if (!resp.ok) throw new Error('HTTP ' + resp.status);
            return resp.arrayBuffer();
        });
    }

    // ─── PDA: fetch pre-built JSON prices (no decompression needed) ──

    function fetchPricesJSON() {
        return new Promise(function(resolve, reject) {
            if (typeof GM_xmlhttpRequest === 'function') {
                GM_xmlhttpRequest({
                    method: 'GET',
                    url: PRICES_JSON_URL,
                    onload: function(resp) {
                        var text = resp.responseText || resp;
                        try {
                            resolve(JSON.parse(text));
                        } catch (e) {
                            reject(new Error('JSON parse failed: ' + e.message));
                        }
                    },
                    onerror: function(err) { reject(err); }
                });
            } else {
                // Last resort: try native fetch for JSON
                fetch(PRICES_JSON_URL).then(function(resp) {
                    if (!resp.ok) throw new Error('HTTP ' + resp.status);
                    return resp.json();
                }).then(resolve).catch(reject);
            }
        });
    }

    // ─── CSV parsing & price computation ─────────────────────

    function parseCSVAndComputePrices(csvText) {
        var lines = csvText.split('\n');
        var weaponGroups = {};  // weapon+rarity -> [prices]
        var bonusGroups = {};   // bonus+rarity -> [prices]
        var classGroups = {};   // class+rarity -> [prices]
        var comboGroups = {};   // weapon|bonus|rarity -> [prices]

        for (var i = 1; i < lines.length; i++) {
            var line = lines[i].trim();
            if (!line) continue;

            var cols = line.split(',');
            if (cols.length < 15) continue;

            var price = parseInt(cols[1], 10);
            var itemId = cols[6];
            var rarity = cols[9];

            // Skip Grey (rarity 1) items
            if (rarity === '1' || !RARITY_MAP[rarity]) continue;

            var rarityName = RARITY_MAP[rarity];
            var weaponName = ITEM_ID_MAP[itemId];
            if (!weaponName) continue;
            if (isNaN(price) || price <= 0) continue;

            // Weapon + rarity group
            var wKey = weaponName + '|' + rarityName;
            if (!weaponGroups[wKey]) weaponGroups[wKey] = [];
            weaponGroups[wKey].push(price);

            // Bonus groups + combo groups
            var bonusId1 = cols[14];
            if (bonusId1 && BONUS_ID_MAP[bonusId1]) {
                var bName1 = BONUS_ID_MAP[bonusId1];
                var bKey1 = bName1 + '|' + rarityName;
                if (!bonusGroups[bKey1]) bonusGroups[bKey1] = [];
                bonusGroups[bKey1].push(price);
                // Weapon+bonus combo
                var cbKey1 = weaponName + '|' + bName1 + '|' + rarityName;
                if (!comboGroups[cbKey1]) comboGroups[cbKey1] = [];
                comboGroups[cbKey1].push(price);
            }
            if (cols.length > 16) {
                var bonusId2 = cols[16];
                if (bonusId2 && BONUS_ID_MAP[bonusId2]) {
                    var bName2 = BONUS_ID_MAP[bonusId2];
                    var bKey2 = bName2 + '|' + rarityName;
                    if (!bonusGroups[bKey2]) bonusGroups[bKey2] = [];
                    bonusGroups[bKey2].push(price);
                    // Weapon+bonus combo
                    var cbKey2 = weaponName + '|' + bName2 + '|' + rarityName;
                    if (!comboGroups[cbKey2]) comboGroups[cbKey2] = [];
                    comboGroups[cbKey2].push(price);
                }
            }

            // Class group
            var cls = WEAPON_CLASS[weaponName];
            if (cls) {
                var cKey = cls + '|' + rarityName;
                if (!classGroups[cKey]) classGroups[cKey] = [];
                classGroups[cKey].push(price);
            }
        }

        // Compute percentiles for each group
        var newWeaponPrices = {};
        Object.keys(weaponGroups).forEach(function(key) {
            var parts = key.split('|');
            var name = parts[0];
            var rar = parts[1];
            var arr = weaponGroups[key].sort(function(a, b) { return a - b; });
            if (!newWeaponPrices[name]) newWeaponPrices[name] = {};
            newWeaponPrices[name][rar] = [
                Math.round(percentile(arr, 25)),
                Math.round(percentile(arr, 50)),
                Math.round(percentile(arr, 75)),
                arr.length
            ];
        });

        var newBonusPrices = {};
        Object.keys(bonusGroups).forEach(function(key) {
            var parts = key.split('|');
            var name = parts[0];
            var rar = parts[1];
            var arr = bonusGroups[key].sort(function(a, b) { return a - b; });
            if (!newBonusPrices[name]) newBonusPrices[name] = {};
            newBonusPrices[name][rar] = [
                Math.round(percentile(arr, 25)),
                Math.round(percentile(arr, 50)),
                Math.round(percentile(arr, 75)),
                arr.length
            ];
        });

        var newClassPrices = {};
        Object.keys(classGroups).forEach(function(key) {
            var parts = key.split('|');
            var name = parts[0];
            var rar = parts[1];
            var arr = classGroups[key].sort(function(a, b) { return a - b; });
            if (!newClassPrices[name]) newClassPrices[name] = {};
            newClassPrices[name][rar] = [
                Math.round(percentile(arr, 25)),
                Math.round(percentile(arr, 50)),
                Math.round(percentile(arr, 75)),
                arr.length
            ];
        });

        // Compute combo percentiles (weapon+bonus)
        var newComboPrices = {};
        Object.keys(comboGroups).forEach(function(key) {
            var parts = key.split('|');
            var weapon = parts[0];
            var bonus = parts[1];
            var rar = parts[2];
            var arr = comboGroups[key].sort(function(a, b) { return a - b; });
            if (arr.length < COMBO_MIN_SAMPLES) return; // skip thin data
            var comboKey = weapon + '|' + bonus;
            if (!newComboPrices[comboKey]) newComboPrices[comboKey] = {};
            newComboPrices[comboKey][rar] = [
                Math.round(percentile(arr, 25)),
                Math.round(percentile(arr, 50)),
                Math.round(percentile(arr, 75)),
                arr.length
            ];
        });

        return {
            weaponPrices: newWeaponPrices,
            bonusPrices: newBonusPrices,
            classPrices: newClassPrices,
            comboPrices: newComboPrices
        };
    }

    // ─── Armour CSV parsing & price computation ────────────────

    function parseArmourCSVAndComputePrices(csvText) {
        var lines = csvText.split('\n');
        var armourGroups = {};   // armour+rarity -> [prices]
        var bonusGroups = {};    // bonus+rarity -> [prices]
        var setGroups = {};      // set+rarity -> [prices]
        var comboGroups = {};    // armour|bonus|rarity -> [prices]

        for (var i = 1; i < lines.length; i++) {
            var line = lines[i].trim();
            if (!line) continue;

            var cols = line.split(',');
            if (cols.length < 15) continue;

            var price = parseInt(cols[1], 10);
            var itemId = cols[6];
            var rarity = cols[9];

            if (rarity === '1' || !RARITY_MAP[rarity]) continue;

            var rarityName = RARITY_MAP[rarity];
            var armourName = ARMOUR_ID_MAP[itemId];
            if (!armourName) continue;
            if (isNaN(price) || price <= 0) continue;

            // Armour + rarity group
            var aKey = armourName + '|' + rarityName;
            if (!armourGroups[aKey]) armourGroups[aKey] = [];
            armourGroups[aKey].push(price);

            // Bonus groups + combo groups
            var bonusId1 = cols[14];
            if (bonusId1 && ARMOUR_BONUS_MAP[bonusId1]) {
                var bName1 = ARMOUR_BONUS_MAP[bonusId1];
                var bKey1 = bName1 + '|' + rarityName;
                if (!bonusGroups[bKey1]) bonusGroups[bKey1] = [];
                bonusGroups[bKey1].push(price);
                var cbKey1 = armourName + '|' + bName1 + '|' + rarityName;
                if (!comboGroups[cbKey1]) comboGroups[cbKey1] = [];
                comboGroups[cbKey1].push(price);
            }
            if (cols.length > 16) {
                var bonusId2 = cols[16];
                if (bonusId2 && ARMOUR_BONUS_MAP[bonusId2]) {
                    var bName2 = ARMOUR_BONUS_MAP[bonusId2];
                    var bKey2 = bName2 + '|' + rarityName;
                    if (!bonusGroups[bKey2]) bonusGroups[bKey2] = [];
                    bonusGroups[bKey2].push(price);
                    var cbKey2 = armourName + '|' + bName2 + '|' + rarityName;
                    if (!comboGroups[cbKey2]) comboGroups[cbKey2] = [];
                    comboGroups[cbKey2].push(price);
                }
            }

            // Set group
            var setName = ARMOUR_SET[armourName];
            if (setName) {
                var sKey = setName + '|' + rarityName;
                if (!setGroups[sKey]) setGroups[sKey] = [];
                setGroups[sKey].push(price);
            }
        }

        var newArmourPrices = {};
        Object.keys(armourGroups).forEach(function(key) {
            var parts = key.split('|');
            var name = parts[0];
            var rar = parts[1];
            var arr = armourGroups[key].sort(function(a, b) { return a - b; });
            if (!newArmourPrices[name]) newArmourPrices[name] = {};
            newArmourPrices[name][rar] = [
                Math.round(percentile(arr, 25)),
                Math.round(percentile(arr, 50)),
                Math.round(percentile(arr, 75)),
                arr.length
            ];
        });

        var newBonusPrices = {};
        Object.keys(bonusGroups).forEach(function(key) {
            var parts = key.split('|');
            var name = parts[0];
            var rar = parts[1];
            var arr = bonusGroups[key].sort(function(a, b) { return a - b; });
            if (!newBonusPrices[name]) newBonusPrices[name] = {};
            newBonusPrices[name][rar] = [
                Math.round(percentile(arr, 25)),
                Math.round(percentile(arr, 50)),
                Math.round(percentile(arr, 75)),
                arr.length
            ];
        });

        var newSetPrices = {};
        Object.keys(setGroups).forEach(function(key) {
            var parts = key.split('|');
            var name = parts[0];
            var rar = parts[1];
            var arr = setGroups[key].sort(function(a, b) { return a - b; });
            if (!newSetPrices[name]) newSetPrices[name] = {};
            newSetPrices[name][rar] = [
                Math.round(percentile(arr, 25)),
                Math.round(percentile(arr, 50)),
                Math.round(percentile(arr, 75)),
                arr.length
            ];
        });

        // Compute armour combo percentiles
        var newComboPrices = {};
        Object.keys(comboGroups).forEach(function(key) {
            var parts = key.split('|');
            var armour = parts[0];
            var bonus = parts[1];
            var rar = parts[2];
            var arr = comboGroups[key].sort(function(a, b) { return a - b; });
            if (arr.length < COMBO_MIN_SAMPLES) return;
            var comboKey = armour + '|' + bonus;
            if (!newComboPrices[comboKey]) newComboPrices[comboKey] = {};
            newComboPrices[comboKey][rar] = [
                Math.round(percentile(arr, 25)),
                Math.round(percentile(arr, 50)),
                Math.round(percentile(arr, 75)),
                arr.length
            ];
        });

        return {
            armourPrices: newArmourPrices,
            armourBonusPrices: newBonusPrices,
            armourSetPrices: newSetPrices,
            comboPrices: newComboPrices
        };
    }

    // ─── Load cached data or defaults ────────────────────────

    function loadCachedPrices() {
        var cached = safeGet(CACHE_KEY, null);
        if (cached && typeof cached === 'string') {
            try { cached = JSON.parse(cached); } catch (e) { cached = null; }
        }
        if (cached && cached.weaponPrices && cached.timestamp) {
            weaponPrices = cached.weaponPrices;
            bonusPrices = cached.bonusPrices;
            classPrices = cached.classPrices;
            if (cached.armourPrices) armourPrices = cached.armourPrices;
            if (cached.armourBonusPrices) armourBonusPrices = cached.armourBonusPrices;
            if (cached.armourSetPrices) armourSetPrices = cached.armourSetPrices;
            if (cached.weaponComboPrices) weaponComboPrices = cached.weaponComboPrices;
            if (cached.armourComboPrices) armourComboPrices = cached.armourComboPrices;
            return cached.timestamp;
        }
        return 0;
    }

    function isCacheStale(timestamp) {
        return !timestamp || (Date.now() - timestamp) > CACHE_TTL;
    }

    // ─── Fetch, parse, cache, and apply ──────────────────────

    async function fetchAndUpdatePrices() {
        if (isFetching) return;
        isFetching = true;
        setToggleLoading(true);

        try {
            if (isPDA) {
                // PDA path: fetch lightweight pre-built JSON (no gzip decompression)
                console.log('[RWP] PDA detected — fetching pre-built JSON prices');
                var jsonData = await fetchPricesJSON();

                if (jsonData.weaponPrices) weaponPrices = jsonData.weaponPrices;
                if (jsonData.bonusPrices) bonusPrices = jsonData.bonusPrices;
                if (jsonData.classPrices) classPrices = jsonData.classPrices;
                if (jsonData.armourPrices) armourPrices = jsonData.armourPrices;
                if (jsonData.armourBonusPrices) armourBonusPrices = jsonData.armourBonusPrices;
                if (jsonData.armourSetPrices) armourSetPrices = jsonData.armourSetPrices;
                if (jsonData.weaponComboPrices) weaponComboPrices = jsonData.weaponComboPrices;
                if (jsonData.armourComboPrices) armourComboPrices = jsonData.armourComboPrices;

                var wCount = Object.keys(weaponPrices).length;
                var cCount = Object.keys(weaponComboPrices).length;
                console.log('[RWP] JSON update complete — ' + wCount + ' weapons, ' + cCount + ' combos loaded');
            } else {
                // Desktop path: fetch full gzipped CSVs and parse
                var results = await Promise.all([
                    fetchGzip(WEAPON_CDN_URL).then(decompressGzip),
                    fetchGzip(ARMOUR_CDN_URL).then(decompressGzip)
                ]);

                var weaponData = parseCSVAndComputePrices(results[0]);
                weaponPrices = weaponData.weaponPrices;
                bonusPrices = weaponData.bonusPrices;
                classPrices = weaponData.classPrices;
                weaponComboPrices = weaponData.comboPrices;

                var armourData = parseArmourCSVAndComputePrices(results[1]);
                armourPrices = armourData.armourPrices;
                armourBonusPrices = armourData.armourBonusPrices;
                armourSetPrices = armourData.armourSetPrices;
                armourComboPrices = armourData.comboPrices;

                var wCount = Object.keys(weaponData.weaponPrices).length;
                var cCount = Object.keys(weaponData.comboPrices).length;
                console.log('[RWP] Live CDN update complete — ' + wCount + ' weapons, ' + cCount + ' combos loaded');
            }

            var cacheData = JSON.stringify({
                weaponPrices: weaponPrices,
                bonusPrices: bonusPrices,
                classPrices: classPrices,
                armourPrices: armourPrices,
                armourBonusPrices: armourBonusPrices,
                armourSetPrices: armourSetPrices,
                weaponComboPrices: weaponComboPrices,
                armourComboPrices: armourComboPrices,
                timestamp: Date.now()
            });
            safeSet(CACHE_KEY, cacheData);

            // Re-inject badges with fresh data
            removeAllBadges();
            injectPriceTags();
            flashButton('#22c55e'); // green = live data success
        } catch (e) {
            console.error('[RWP] Fetch failed, using fallback data:', e);
            flashButton('#ef4444'); // red = fetch failed, using defaults/cache
        } finally {
            isFetching = false;
            setToggleLoading(false);
        }
    }

    // ─── Toggle button flash feedback ────────────────────────

    function flashButton(color) {
        var btn = document.getElementById('rwp-inline-toggle');
        if (!btn) return;
        btn.style.borderColor = color;
        btn.style.color = color;
        btn.style.boxShadow = '0 0 10px ' + color + '80';
        setTimeout(function() {
            btn.style.borderColor = '';
            btn.style.color = '';
            btn.style.boxShadow = '';
        }, 2000);
    }

    // ─── Toggle button loading state ─────────────────────────

    function setToggleLoading(loading) {
        var btn = document.getElementById('rwp-inline-toggle');
        if (!btn) return;
        if (loading) {
            btn.classList.add('rwp-loading');
            btn.textContent = '';
            var spinner = document.createElement('span');
            spinner.className = 'rwp-spinner';
            btn.appendChild(spinner);
        } else {
            btn.classList.remove('rwp-loading');
            btn.textContent = '$';
        }
    }

    // ─── Rarity detection ────────────────────────────────────

    function detectRarity(el) {
        // Method 1: React rarity element
        var rarityEl = el.querySelector('[class*="rarity___"]');
        if (rarityEl) {
            var txt = (rarityEl.textContent || '').toLowerCase();
            if (txt.indexOf('red') !== -1) return 'Red';
            if (txt.indexOf('orange') !== -1) return 'Orange';
            if (txt.indexOf('yellow') !== -1) return 'Yellow';
        }

        // Method 2: glow-* class on container or children
        var html = el.className || '';
        var inner = el.innerHTML || '';
        var combined = html + ' ' + inner;
        if (/glow-red/i.test(combined)) return 'Red';
        if (/glow-orange/i.test(combined)) return 'Orange';
        if (/glow-yellow/i.test(combined)) return 'Yellow';

        // Method 3: extraordinary / extremely-rare class
        if (/extremely[_-]?rare/i.test(combined)) return 'Red';
        if (/extraordinary/i.test(combined)) return 'Orange';

        return null;
    }

    // ─── Bonus name normalization ─────────────────────────────
    // DOM may show "Double Tap" but data key is "Double-Tap", or "HomeRun" vs "Home Run"
    var BONUS_ALIAS = {};
    (function buildBonusAlias() {
        var allBonusNames = Object.keys(bonusPrices).concat(Object.keys(armourBonusPrices));
        for (var i = 0; i < allBonusNames.length; i++) {
            var n = allBonusNames[i];
            BONUS_ALIAS[n.toLowerCase()] = n;
            // "Double-Tap" -> alias "double tap"
            BONUS_ALIAS[n.replace(/-/g, ' ').toLowerCase()] = n;
            // "HomeRun" -> alias "home run"
            BONUS_ALIAS[n.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase()] = n;
        }
    })();

    function resolveBonusName(raw) {
        if (!raw) return null;
        var t = raw.trim();
        if (bonusPrices[t] || armourBonusPrices[t]) return t;
        var lower = t.toLowerCase();
        if (BONUS_ALIAS[lower]) return BONUS_ALIAS[lower];
        // Try hyphenating spaces: "Double Tap" -> "Double-Tap"
        var hyph = t.replace(/\s+/g, '-');
        if (bonusPrices[hyph] || armourBonusPrices[hyph]) return hyph;
        // Try removing spaces: "Home Run" -> "HomeRun"
        var joined = t.replace(/\s+/g, '');
        if (bonusPrices[joined] || armourBonusPrices[joined]) return joined;
        return null;
    }

    // ─── Bonus extraction ────────────────────────────────────

    function extractBonuses(el) {
        var bonuses = [];

        // React: aria-label containing "Bonus"
        var ariaEls = el.querySelectorAll('[aria-label*="Bonus"]');
        for (var i = 0; i < ariaEls.length; i++) {
            var label = ariaEls[i].getAttribute('aria-label') || '';
            // e.g. "Bonus: Warlord" or "Bonus - Warlord"
            var match = label.match(/Bonus[:\s\-]+(\w[\w\s-]*)/i);
            if (match) {
                var bName = resolveBonusName(match[1]);
                if (bName && bonuses.indexOf(bName) === -1) bonuses.push(bName);
            }
        }

        // React: property wrapper with bonus text
        var propEls = el.querySelectorAll('li[class*="propertyWrapper"]');
        for (var j = 0; j < propEls.length; j++) {
            var propLabel = propEls[j].getAttribute('aria-label') || '';
            var propMatch = propLabel.match(/Bonus[:\s\-]+(\w[\w\s-]*)/i);
            if (propMatch) {
                var pName = resolveBonusName(propMatch[1]);
                if (pName && bonuses.indexOf(pName) === -1) bonuses.push(pName);
            }
        }

        // Auction house: .iconsbonuses span with title (titles contain HTML like "<b>Motivation</b> 15%")
        var legacySpans = el.querySelectorAll('.iconsbonuses span');
        for (var k = 0; k < legacySpans.length; k++) {
            var title = legacySpans[k].getAttribute('title') || '';
            // Try HTML-wrapped name first: <b>BonusName</b>
            var htmlMatch = title.match(/<b>([\w\s-]+)<\/b>/i);
            if (htmlMatch) {
                var hName = resolveBonusName(htmlMatch[1]);
                if (hName && bonuses.indexOf(hName) === -1) bonuses.push(hName);
            } else {
                // Plain text fallback
                var lMatch = title.match(/^(\w[\w\s-]*)/);
                if (lMatch) {
                    var lName = resolveBonusName(lMatch[1]);
                    if (lName && bonuses.indexOf(lName) === -1) bonuses.push(lName);
                }
            }
        }

        // Auction house: display-bonus plugin p elements (e.g. "Motivation 15%")
        var dbBonuses = el.querySelectorAll('p.display-bonus__bonus, [class*="display-bonus__bonus"]');
        for (var d = 0; d < dbBonuses.length; d++) {
            var dbText = dbBonuses[d].textContent || '';
            var dbMatch = dbText.match(/^\s*(\w[\w\s-]*)/);
            if (dbMatch) {
                var dbName = resolveBonusName(dbMatch[1]);
                if (dbName && bonuses.indexOf(dbName) === -1) bonuses.push(dbName);
            }
        }

        return bonuses;
    }

    // ─── Weapon name extraction ──────────────────────────────

    function extractWeaponName(el) {
        // React: [class*="description"] .bold
        var descBold = el.querySelector('[class*="description"] .bold');
        if (descBold) return normalizeWeaponName(descBold.textContent);

        // React: [class*="itemName"]
        var itemName = el.querySelector('[class*="itemName"]');
        if (itemName) return normalizeWeaponName(itemName.textContent);

        // Legacy: .item-name
        var legacyName = el.querySelector('.item-name');
        if (legacyName) return normalizeWeaponName(legacyName.textContent);

        // Legacy: .name-wrap .name
        var nameWrap = el.querySelector('.name-wrap .name');
        if (nameWrap) return normalizeWeaponName(nameWrap.textContent);

        // Fallback: title or alt on img
        var img = el.querySelector('img[alt], img[title]');
        if (img) {
            var alt = img.getAttribute('alt') || img.getAttribute('title') || '';
            if (alt) return normalizeWeaponName(alt);
        }

        return '';
    }

    // ─── Badge creation ──────────────────────────────────────

    function createBadge(itemName, rarity, median, bonuses, bonusFn, estimatedPrice, priceArray, bonusPriceArrays) {
        var color = RARITY_COLORS[rarity] || '#e8c44a';
        var badge = document.createElement('span');
        badge.className = 'rwp-price-tag';
        badge.setAttribute('data-rwp-priced', '1');

        // Store data for tooltip
        badge.setAttribute('data-rwp-item', itemName);
        badge.setAttribute('data-rwp-rarity', rarity);
        if (priceArray) badge.setAttribute('data-rwp-prices', JSON.stringify(priceArray));
        if (bonusPriceArrays) badge.setAttribute('data-rwp-bonus-prices', JSON.stringify(bonusPriceArrays));
        if (bonuses.length > 0) badge.setAttribute('data-rwp-bonuses', JSON.stringify(bonuses));

        var displayPrice = estimatedPrice || median;
        var label = (bonuses.length > 0 && estimatedPrice && estimatedPrice !== median) ? 'RWP Est' : 'RWP';

        var html = '<span class="rwp-price-tag-inner">' +
            '<span class="rwp-price-tag-label">' + label + '</span>' +
            '<span class="rwp-price-tag-value" style="color:' + color + ';">' + fmtMoney(displayPrice) + '</span>' +
            '</span>';
        badge.innerHTML = html;

        badge.addEventListener('click', function(e) {
            e.stopPropagation();
            showPriceTooltip(badge);
        });

        return badge;
    }

    // ─── Tooltip ──────────────────────────────────────────────

    var activeTooltip = null;

    function closeActiveTooltip() {
        if (activeTooltip) {
            activeTooltip.remove();
            activeTooltip = null;
        }
    }

    function showPriceTooltip(badge) {
        // If clicking the same badge, toggle off
        if (activeTooltip && activeTooltip._rwpBadge === badge) {
            closeActiveTooltip();
            return;
        }
        closeActiveTooltip();

        var itemName = badge.getAttribute('data-rwp-item') || 'Unknown';
        var rarity = badge.getAttribute('data-rwp-rarity') || 'Yellow';
        var color = RARITY_COLORS[rarity] || '#e8c44a';
        var prices = null;
        var bonusPricesData = null;
        var bonuses = null;

        try { prices = JSON.parse(badge.getAttribute('data-rwp-prices')); } catch (e) {}
        try { bonusPricesData = JSON.parse(badge.getAttribute('data-rwp-bonus-prices')); } catch (e) {}
        try { bonuses = JSON.parse(badge.getAttribute('data-rwp-bonuses')); } catch (e) {}

        var tooltip = document.createElement('div');
        tooltip.className = 'rwp-price-tooltip';
        tooltip._rwpBadge = badge;

        var html = '<div class="rwp-tooltip-header" style="color:' + color + ';">' + itemName + ' <span style="opacity:0.6;">(' + rarity + ')</span></div>';

        if (prices && prices.length === 4) {
            html += '<div class="rwp-tooltip-section">';
            html += '<div class="rwp-tooltip-row"><span class="rwp-tooltip-label">Min:</span><span class="rwp-tooltip-value">' + fmtMoney(prices[0]) + '</span></div>';
            html += '<div class="rwp-tooltip-row"><span class="rwp-tooltip-label">Median:</span><span class="rwp-tooltip-value">' + fmtMoney(prices[1]) + '</span></div>';
            html += '<div class="rwp-tooltip-row"><span class="rwp-tooltip-label">Max:</span><span class="rwp-tooltip-value">' + fmtMoney(prices[2]) + '</span></div>';
            html += '<div class="rwp-tooltip-row"><span class="rwp-tooltip-label">Auctions:</span><span class="rwp-tooltip-value">' + prices[3] + '</span></div>';
            html += '</div>';
        }

        if (bonuses && bonusPricesData) {
            for (var i = 0; i < bonuses.length; i++) {
                var bName = bonuses[i];
                var bArr = bonusPricesData[bName];
                if (!bArr || bArr.length !== 4) continue;
                html += '<div class="rwp-tooltip-divider"></div>';
                html += '<div class="rwp-tooltip-bonus-header">' + bName + ' Bonus</div>';
                html += '<div class="rwp-tooltip-section">';
                html += '<div class="rwp-tooltip-row"><span class="rwp-tooltip-label">Min:</span><span class="rwp-tooltip-value">' + fmtMoney(bArr[0]) + '</span></div>';
                html += '<div class="rwp-tooltip-row"><span class="rwp-tooltip-label">Median:</span><span class="rwp-tooltip-value">' + fmtMoney(bArr[1]) + '</span></div>';
                html += '<div class="rwp-tooltip-row"><span class="rwp-tooltip-label">Max:</span><span class="rwp-tooltip-value">' + fmtMoney(bArr[2]) + '</span></div>';
                html += '<div class="rwp-tooltip-row"><span class="rwp-tooltip-label">Auctions:</span><span class="rwp-tooltip-value">' + bArr[3] + '</span></div>';
                html += '</div>';
            }
        }

        tooltip.innerHTML = html;
        document.body.appendChild(tooltip);

        // Position tooltip near badge
        var rect = badge.getBoundingClientRect();
        var tooltipRect = tooltip.getBoundingClientRect();
        var top = rect.bottom + window.scrollY + 6;
        var left = rect.left + window.scrollX + (rect.width / 2) - (tooltipRect.width / 2);

        // Keep within viewport horizontally
        if (left < 4) left = 4;
        if (left + tooltipRect.width > window.innerWidth - 4) left = window.innerWidth - tooltipRect.width - 4;

        tooltip.style.top = top + 'px';
        tooltip.style.left = left + 'px';

        activeTooltip = tooltip;
    }

    document.addEventListener('click', function(e) {
        if (activeTooltip && !activeTooltip.contains(e.target) && !e.target.closest('.rwp-price-tag')) {
            closeActiveTooltip();
        }
    });

